[SysMessageTypeFactory(SysMessageType::METPEpricingSmall)]
internal final class METPEPricingMessageSmallType extends SysMessageTypeMetadata
{
    #OCCRetryCount
}

Method.Source:
 /// <summary>
/// Copied from ProdProductionOrderMessageTypeBase
/// Needs to be overridden for nested contracts due to a deserialization bug that
/// ignores the rest of the contract after encountering an unknown object field.
/// </summary>
/// <returns></returns>
public ClassId contractClass()
{
    return classNum(METSendPEPricingRequest);
}

internal List getDependencies(SysMessage _message)
{
    List dependencies = new List(Types::Record);

    return dependencies;
}

internal boolean canSendMessage(SysMessageQueue _messageQueue, SysMessageTargetRecId _messageTarget, SysMessageTargetRecId _sourceMessageTarget)
{
    return _messageQueue == SysMessageQueue::METSendPEPricingSmallQueue;
}

internal void processMessageStateTransition(SysMessage _message, SysMessageStateTransition _messageStateTransition)
{
    if (_messageStateTransition.isEqual(SysMessageStateTransition::newFromStates(SysMessageState::Queued, SysMessageState::Processed)))
    {
        this.processMessage(this.getContract(_message));
    }
}

private void processMessage(METSendPEPricingRequest _contract)
{
    try
    {
        METSendPEPricingEngine  sendPEpricingEngine = new METSendPEPricingEngine();

        sendPEpricingEngine.sendPEPricingMessage(_contract);

    }
    catch (Exception::UpdateConflict)
    {
        if (xSession::currentRetryCount() >= #RetryNum)
        {
            throw Exception::UpdateConflictNotRecovered;
        }
        else
        {
            retry;
        }
    }
}

private METSendPEPricingRequest getContract(SysMessage _message)
{
    METSendPEPricingRequest contract = FormJsonSerializer::deserializeObject(this.contractClass(), _message.Content);

    return contract;
}

/// <summary>
/// to fix error cannot send message to the queue from external source
/// </summary>
/// <param name = "_messageQueue"></param>
/// <param name = "_companyId"></param>
/// <returns></returns>
public boolean canSendMessageUsingMessageService(SysMessageQueue _messageQueue, CompanyId _companyId)
{
    return true;
}
